"""Fingerprint constants for Jacobian-based contact classification.

These tensors encode the coupling patterns (base-pair, repeat, protein) used to
classify Jacobian-derived contacts into multimodal channels. They live in a
standalone module so they can be imported without pulling in the classification
code.

The *_COSINE and *_RINALMO patterns are currently unused; they are retained for
future use and not imported by jacobian.py.
"""

from typing import List, Sequence, Tuple

import torch


# Public token-string defaults for categorical Jacobian/fingerprinting.
# Nucleotide order must match the 4x4 fingerprint channel order below.
MINERVA_NUCLEOTIDE_TOKENS: Tuple[str, ...] = ("a", "t", "g", "c")


# Argmax patterns: which token index has the highest coupling for each input token.
# Channel ordering: [a=0, t=1, g=2, c=3].
# Base-pair pattern: a->t (1), t->a (0), g->c (3), c->g (2) - Watson-Crick.
BASE_PAIR_ARGMAX = torch.tensor([1, 0, 3, 2])  # a->t, t->a, g->c, c->g

# Repeat pattern: identity (same nucleotide couples strongest).
REPEAT_ARGMAX = torch.tensor([0, 1, 2, 3])  # a->a, t->t, g->g, c->c

# Cosine-similarity reference matrices (4x4 coupling patterns).
# Channel ordering: [a=0, t=1, g=2, c=3].
