# Protein fingerprint in the Minerva amino-acid ordering.
# Minerva ordering: ['A','C','F','I','L','M','V','W','Y','P','H','K','R','D','E','N','Q','S','T','G']
# If the Jacobian uses a different AA channel ordering (e.g. alphabetical
# 'ACDEFGHIKLMNPQRSTVWY'), pass jac_aa_order to the classification function.
MINERVA_AA_ORDER = ['A', 'C', 'F', 'I', 'L', 'M', 'V', 'W', 'Y', 'P', 'H', 'K', 'R', 'D', 'E', 'N', 'Q', 'S', 'T', 'G']
MINERVA_AMINO_ACID_TOKENS: Tuple[str, ...] = tuple(MINERVA_AA_ORDER)


def _tokens_to_ids(tokenizer, tokens: Sequence[str], name: str) -> List[int]:
    vocab = tokenizer.get_vocab()
    missing = [token for token in tokens if token not in vocab]
    if missing:
        raise ValueError(f"Tokenizer is missing Minerva {name} token(s): {missing}")
    return [vocab[token] for token in tokens]


def get_minerva_token_ids(tokenizer) -> Tuple[List[int], List[int]]:
    """Return default ``(nuc_token_ids, aa_token_ids)`` for Minerva Jacobians.

    Nucleotide IDs follow ``MINERVA_NUCLEOTIDE_TOKENS`` (a, t, g, c), matching
    the baked fingerprint channel order. Amino-acid IDs follow
    ``MINERVA_AMINO_ACID_TOKENS``, which matches the protein fingerprint order.
    """
    return (
        _tokens_to_ids(tokenizer, MINERVA_NUCLEOTIDE_TOKENS, "nucleotide"),
        _tokens_to_ids(tokenizer, MINERVA_AMINO_ACID_TOKENS, "amino-acid"),
    )


